// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListAudit The audit log, newest first
	// (GET /audit)
	ListAudit(w http.ResponseWriter, r *http.Request, params ListAuditParams)
	// Login Sign in with a username and password
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout End the current session
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// GetMe The signed-in user, role and permissions
	// (GET /auth/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// VerifyMFA Complete sign-in with a TOTP code
	// (POST /auth/mfa)
	VerifyMFA(w http.ResponseWriter, r *http.Request)
	// StartMFAEnrolment Begin TOTP enrolment (returns the secret once)
	// (POST /auth/mfa/enroll)
	StartMFAEnrolment(w http.ResponseWriter, r *http.Request)
	// ConfirmMFAEnrolment Confirm enrolment with a first code; completes sign-in
	// (POST /auth/mfa/enroll/confirm)
	ConfirmMFAEnrolment(w http.ResponseWriter, r *http.Request)
	// ListBans Active temporary bans (manual, automatic and CrowdSec)
	// (GET /bans)
	ListBans(w http.ResponseWriter, r *http.Request)
	// CreateBan Ban an address for a while (every site, or one)
	// (POST /bans)
	CreateBan(w http.ResponseWriter, r *http.Request)
	// DeleteBan Lift a ban
	// (DELETE /bans/{id})
	DeleteBan(w http.ResponseWriter, r *http.Request, id string)
	// ListBlockPages Custom block page templates
	// (GET /block-pages)
	ListBlockPages(w http.ResponseWriter, r *http.Request)
	// DeleteBlockPage Delete a block page template (refused while a policy uses it)
	// (DELETE /block-pages/{id})
	DeleteBlockPage(w http.ResponseWriter, r *http.Request, id string)
	// PutBlockPage Create or replace a block page template (validated and rendered once with sample data)
	// (PUT /block-pages/{id})
	PutBlockPage(w http.ResponseWriter, r *http.Request, id string)
	// ListCertificates Uploaded certificates (never includes private keys)
	// (GET /certificates)
	ListCertificates(w http.ResponseWriter, r *http.Request)
	// UploadCertificate Upload a PEM certificate chain and its private key
	// (POST /certificates)
	UploadCertificate(w http.ResponseWriter, r *http.Request)
	// GetACMEStatus Certificate state for every site host that uses automatic certificates
	// (GET /certificates/acme-status)
	GetACMEStatus(w http.ResponseWriter, r *http.Request)
	// DeleteCertificate Delete an uploaded certificate (refused while a site uses it)
	// (DELETE /certificates/{id})
	DeleteCertificate(w http.ResponseWriter, r *http.Request, id string)
	// GetConfig The live configuration (with defaults applied)
	// (GET /config)
	GetConfig(w http.ResponseWriter, r *http.Request)
	// PutConfig Replace the whole configuration
	// (PUT /config)
	PutConfig(w http.ResponseWriter, r *http.Request, params PutConfigParams)
	// ValidateConfig Validate a configuration without applying it
	// (POST /config/validate)
	ValidateConfig(w http.ResponseWriter, r *http.Request)
	// ListConfigVersions Configuration history, newest first
	// (GET /config/versions)
	ListConfigVersions(w http.ResponseWriter, r *http.Request, params ListConfigVersionsParams)
	// GetConfigVersion One version with its snapshot and diff
	// (GET /config/versions/{id})
	GetConfigVersion(w http.ResponseWriter, r *http.Request, id VersionID)
	// RollbackConfig Apply an earlier version's snapshot as a new version
	// (POST /config/versions/{id}/rollback)
	RollbackConfig(w http.ResponseWriter, r *http.Request, id VersionID, params RollbackConfigParams)
	// GetDefaults Global policy defaults
	// (GET /defaults)
	GetDefaults(w http.ResponseWriter, r *http.Request)
	// PutDefaults Replace the global policy defaults
	// (PUT /defaults)
	PutDefaults(w http.ResponseWriter, r *http.Request, params PutDefaultsParams)
	// ListEvents Security events, newest first
	// (GET /events)
	ListEvents(w http.ResponseWriter, r *http.Request, params ListEventsParams)
	// GetEvent One event
	// (GET /events/{id})
	GetEvent(w http.ResponseWriter, r *http.Request, id string)
	// GetFeedsStatus Health of the GeoIP, reputation and CrowdSec feeds
	// (GET /feeds/status)
	GetFeedsStatus(w http.ResponseWriter, r *http.Request)
	// GetWouldBlockReport Requests a detect-mode site would have blocked (anomaly score reached the blocking threshold), grouped by rule and path
	// (GET /reports/would-block)
	GetWouldBlockReport(w http.ResponseWriter, r *http.Request, params GetWouldBlockReportParams)
	// ExportWouldBlockReport The matching requests of the would-block report as CSV
	// (GET /reports/would-block.csv)
	ExportWouldBlockReport(w http.ResponseWriter, r *http.Request, params ExportWouldBlockReportParams)
	// CreateFirstAdmin Create the first administrator (only while no user exists; needs the one-time setup token)
	// (POST /setup/admin)
	CreateFirstAdmin(w http.ResponseWriter, r *http.Request)
	// GetSetupStatus Whether first-run setup is still open (no users exist)
	// (GET /setup/status)
	GetSetupStatus(w http.ResponseWriter, r *http.Request)
	// ListSites Sites
	// (GET /sites)
	ListSites(w http.ResponseWriter, r *http.Request)
	// CreateSite Add a site
	// (POST /sites)
	CreateSite(w http.ResponseWriter, r *http.Request, params CreateSiteParams)
	// DeleteSite Remove a site
	// (DELETE /sites/{site})
	DeleteSite(w http.ResponseWriter, r *http.Request, site SiteID, params DeleteSiteParams)
	// GetSite One site
	// (GET /sites/{site})
	GetSite(w http.ResponseWriter, r *http.Request, site SiteID)
	// PatchSite Change fields of a site (JSON Merge Patch)
	// (PATCH /sites/{site})
	PatchSite(w http.ResponseWriter, r *http.Request, site SiteID, params PatchSiteParams)
	// GetEffectivePolicy The merged policy for a request, with the source of every value
	// (GET /sites/{site}/effective-policy)
	GetEffectivePolicy(w http.ResponseWriter, r *http.Request, site SiteID, params GetEffectivePolicyParams)
	// ListEndpoints Endpoint overrides of a site
	// (GET /sites/{site}/endpoints)
	ListEndpoints(w http.ResponseWriter, r *http.Request, site SiteID)
	// CreateEndpoint Add an endpoint override
	// (POST /sites/{site}/endpoints)
	CreateEndpoint(w http.ResponseWriter, r *http.Request, site SiteID, params CreateEndpointParams)
	// DeleteEndpoint Remove an endpoint override
	// (DELETE /sites/{site}/endpoints/{endpoint})
	DeleteEndpoint(w http.ResponseWriter, r *http.Request, site SiteID, endpoint EndpointID, params DeleteEndpointParams)
	// GetEndpoint One endpoint override
	// (GET /sites/{site}/endpoints/{endpoint})
	GetEndpoint(w http.ResponseWriter, r *http.Request, site SiteID, endpoint EndpointID)
	// PatchEndpoint Change fields of an endpoint override (JSON Merge Patch)
	// (PATCH /sites/{site}/endpoints/{endpoint})
	PatchEndpoint(w http.ResponseWriter, r *http.Request, site SiteID, endpoint EndpointID, params PatchEndpointParams)
	// GetTimeseries Event counts per time bucket and action, from the per-minute rollups
	// (GET /stats/timeseries)
	GetTimeseries(w http.ResponseWriter, r *http.Request, params GetTimeseriesParams)
	// GetTop Most frequent values of one dimension over a time range
	// (GET /stats/top)
	GetTop(w http.ResponseWriter, r *http.Request, params GetTopParams)
	// ListBackups The node's own backups (scheduled and manual), newest first
	// (GET /system/backups)
	ListBackups(w http.ResponseWriter, r *http.Request)
	// GetSystemInfo Version, engine, features and the audit chain head
	// (GET /system/info)
	GetSystemInfo(w http.ResponseWriter, r *http.Request)
	// GetSystemStatus Storage, event pipeline and feed health for the System page
	// (GET /system/status)
	GetSystemStatus(w http.ResponseWriter, r *http.Request)
	// TestUpstream Check that the proxy can reach an upstream target (connect and HEAD /, no redirects, 3 s)
	// (POST /system/test-upstream)
	TestUpstream(w http.ResponseWriter, r *http.Request)
	// GetUpdateStatus Check whether a newer signed release is available
	// (GET /system/update)
	GetUpdateStatus(w http.ResponseWriter, r *http.Request)
	// ApplyUpdate Download, verify and stage or install the latest signed release
	// (POST /system/update/apply)
	ApplyUpdate(w http.ResponseWriter, r *http.Request)
	// ListTokens Your API tokens (all tokens for an admin)
	// (GET /tokens)
	ListTokens(w http.ResponseWriter, r *http.Request)
	// CreateToken Create an API token (the secret is shown once)
	// (POST /tokens)
	CreateToken(w http.ResponseWriter, r *http.Request)
	// DeleteToken Revoke a token (your own; an admin may revoke any)
	// (DELETE /tokens/{id})
	DeleteToken(w http.ResponseWriter, r *http.Request, id string)
	// ListUsers Users
	// (GET /users)
	ListUsers(w http.ResponseWriter, r *http.Request)
	// CreateUser Create a user
	// (POST /users)
	CreateUser(w http.ResponseWriter, r *http.Request)
	// DeleteUser Delete a user (and their sessions and tokens)
	// (DELETE /users/{id})
	DeleteUser(w http.ResponseWriter, r *http.Request, id UserID)
	// PatchUser Change a user's role, state or password
	// (PATCH /users/{id})
	PatchUser(w http.ResponseWriter, r *http.Request, id UserID)
	// ResetUserMFA Clear a user's MFA enrolment (they re-enrol at next sign-in)
	// (POST /users/{id}/reset-mfa)
	ResetUserMFA(w http.ResponseWriter, r *http.Request, id UserID)
}

