// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListAudit The audit log, newest first
	// (GET /audit)
	ListAudit(ctx context.Context, request ListAuditRequestObject) (ListAuditResponseObject, error)
	// Login Sign in with a username and password
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout End the current session
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// GetMe The signed-in user, role and permissions
	// (GET /auth/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// VerifyMFA Complete sign-in with a TOTP code
	// (POST /auth/mfa)
	VerifyMFA(ctx context.Context, request VerifyMFARequestObject) (VerifyMFAResponseObject, error)
	// StartMFAEnrolment Begin TOTP enrolment (returns the secret once)
	// (POST /auth/mfa/enroll)
	StartMFAEnrolment(ctx context.Context, request StartMFAEnrolmentRequestObject) (StartMFAEnrolmentResponseObject, error)
	// ConfirmMFAEnrolment Confirm enrolment with a first code; completes sign-in
	// (POST /auth/mfa/enroll/confirm)
	ConfirmMFAEnrolment(ctx context.Context, request ConfirmMFAEnrolmentRequestObject) (ConfirmMFAEnrolmentResponseObject, error)
	// ListBans Active temporary bans (manual, automatic and CrowdSec)
	// (GET /bans)
	ListBans(ctx context.Context, request ListBansRequestObject) (ListBansResponseObject, error)
	// CreateBan Ban an address for a while (every site, or one)
	// (POST /bans)
	CreateBan(ctx context.Context, request CreateBanRequestObject) (CreateBanResponseObject, error)
	// DeleteBan Lift a ban
	// (DELETE /bans/{id})
	DeleteBan(ctx context.Context, request DeleteBanRequestObject) (DeleteBanResponseObject, error)
	// ListBlockPages Custom block page templates
	// (GET /block-pages)
	ListBlockPages(ctx context.Context, request ListBlockPagesRequestObject) (ListBlockPagesResponseObject, error)
	// DeleteBlockPage Delete a block page template (refused while a policy uses it)
	// (DELETE /block-pages/{id})
	DeleteBlockPage(ctx context.Context, request DeleteBlockPageRequestObject) (DeleteBlockPageResponseObject, error)
	// PutBlockPage Create or replace a block page template (validated and rendered once with sample data)
	// (PUT /block-pages/{id})
	PutBlockPage(ctx context.Context, request PutBlockPageRequestObject) (PutBlockPageResponseObject, error)
	// ListCertificates Uploaded certificates (never includes private keys)
	// (GET /certificates)
	ListCertificates(ctx context.Context, request ListCertificatesRequestObject) (ListCertificatesResponseObject, error)
	// UploadCertificate Upload a PEM certificate chain and its private key
	// (POST /certificates)
	UploadCertificate(ctx context.Context, request UploadCertificateRequestObject) (UploadCertificateResponseObject, error)
	// GetACMEStatus Certificate state for every site host that uses automatic certificates
	// (GET /certificates/acme-status)
	GetACMEStatus(ctx context.Context, request GetACMEStatusRequestObject) (GetACMEStatusResponseObject, error)
	// DeleteCertificate Delete an uploaded certificate (refused while a site uses it)
	// (DELETE /certificates/{id})
	DeleteCertificate(ctx context.Context, request DeleteCertificateRequestObject) (DeleteCertificateResponseObject, error)
	// GetConfig The live configuration (with defaults applied)
	// (GET /config)
	GetConfig(ctx context.Context, request GetConfigRequestObject) (GetConfigResponseObject, error)
	// PutConfig Replace the whole configuration
	// (PUT /config)
	PutConfig(ctx context.Context, request PutConfigRequestObject) (PutConfigResponseObject, error)
	// ValidateConfig Validate a configuration without applying it
	// (POST /config/validate)
	ValidateConfig(ctx context.Context, request ValidateConfigRequestObject) (ValidateConfigResponseObject, error)
	// ListConfigVersions Configuration history, newest first
	// (GET /config/versions)
	ListConfigVersions(ctx context.Context, request ListConfigVersionsRequestObject) (ListConfigVersionsResponseObject, error)
	// GetConfigVersion One version with its snapshot and diff
	// (GET /config/versions/{id})
	GetConfigVersion(ctx context.Context, request GetConfigVersionRequestObject) (GetConfigVersionResponseObject, error)
	// RollbackConfig Apply an earlier version's snapshot as a new version
	// (POST /config/versions/{id}/rollback)
	RollbackConfig(ctx context.Context, request RollbackConfigRequestObject) (RollbackConfigResponseObject, error)
	// GetDefaults Global policy defaults
	// (GET /defaults)
	GetDefaults(ctx context.Context, request GetDefaultsRequestObject) (GetDefaultsResponseObject, error)
	// PutDefaults Replace the global policy defaults
	// (PUT /defaults)
	PutDefaults(ctx context.Context, request PutDefaultsRequestObject) (PutDefaultsResponseObject, error)
	// ListEvents Security events, newest first
	// (GET /events)
	ListEvents(ctx context.Context, request ListEventsRequestObject) (ListEventsResponseObject, error)
	// GetEvent One event
	// (GET /events/{id})
	GetEvent(ctx context.Context, request GetEventRequestObject) (GetEventResponseObject, error)
	// GetFeedsStatus Health of the GeoIP, reputation and CrowdSec feeds
	// (GET /feeds/status)
	GetFeedsStatus(ctx context.Context, request GetFeedsStatusRequestObject) (GetFeedsStatusResponseObject, error)
	// GetWouldBlockReport Requests a detect-mode site would have blocked (anomaly score reached the blocking threshold), grouped by rule and path
	// (GET /reports/would-block)
	GetWouldBlockReport(ctx context.Context, request GetWouldBlockReportRequestObject) (GetWouldBlockReportResponseObject, error)
	// ExportWouldBlockReport The matching requests of the would-block report as CSV
	// (GET /reports/would-block.csv)
	ExportWouldBlockReport(ctx context.Context, request ExportWouldBlockReportRequestObject) (ExportWouldBlockReportResponseObject, error)
	// CreateFirstAdmin Create the first administrator (only while no user exists; needs the one-time setup token)
	// (POST /setup/admin)
	CreateFirstAdmin(ctx context.Context, request CreateFirstAdminRequestObject) (CreateFirstAdminResponseObject, error)
	// GetSetupStatus Whether first-run setup is still open (no users exist)
	// (GET /setup/status)
	GetSetupStatus(ctx context.Context, request GetSetupStatusRequestObject) (GetSetupStatusResponseObject, error)
	// ListSites Sites
	// (GET /sites)
	ListSites(ctx context.Context, request ListSitesRequestObject) (ListSitesResponseObject, error)
	// CreateSite Add a site
	// (POST /sites)
	CreateSite(ctx context.Context, request CreateSiteRequestObject) (CreateSiteResponseObject, error)
	// DeleteSite Remove a site
	// (DELETE /sites/{site})
	DeleteSite(ctx context.Context, request DeleteSiteRequestObject) (DeleteSiteResponseObject, error)
	// GetSite One site
	// (GET /sites/{site})
	GetSite(ctx context.Context, request GetSiteRequestObject) (GetSiteResponseObject, error)
	// PatchSite Change fields of a site (JSON Merge Patch)
	// (PATCH /sites/{site})
	PatchSite(ctx context.Context, request PatchSiteRequestObject) (PatchSiteResponseObject, error)
	// GetEffectivePolicy The merged policy for a request, with the source of every value
	// (GET /sites/{site}/effective-policy)
	GetEffectivePolicy(ctx context.Context, request GetEffectivePolicyRequestObject) (GetEffectivePolicyResponseObject, error)
	// ListEndpoints Endpoint overrides of a site
	// (GET /sites/{site}/endpoints)
	ListEndpoints(ctx context.Context, request ListEndpointsRequestObject) (ListEndpointsResponseObject, error)
	// CreateEndpoint Add an endpoint override
	// (POST /sites/{site}/endpoints)
	CreateEndpoint(ctx context.Context, request CreateEndpointRequestObject) (CreateEndpointResponseObject, error)
	// DeleteEndpoint Remove an endpoint override
	// (DELETE /sites/{site}/endpoints/{endpoint})
	DeleteEndpoint(ctx context.Context, request DeleteEndpointRequestObject) (DeleteEndpointResponseObject, error)
	// GetEndpoint One endpoint override
	// (GET /sites/{site}/endpoints/{endpoint})
	GetEndpoint(ctx context.Context, request GetEndpointRequestObject) (GetEndpointResponseObject, error)
	// PatchEndpoint Change fields of an endpoint override (JSON Merge Patch)
	// (PATCH /sites/{site}/endpoints/{endpoint})
	PatchEndpoint(ctx context.Context, request PatchEndpointRequestObject) (PatchEndpointResponseObject, error)
	// GetTimeseries Event counts per time bucket and action, from the per-minute rollups
	// (GET /stats/timeseries)
	GetTimeseries(ctx context.Context, request GetTimeseriesRequestObject) (GetTimeseriesResponseObject, error)
	// GetTop Most frequent values of one dimension over a time range
	// (GET /stats/top)
	GetTop(ctx context.Context, request GetTopRequestObject) (GetTopResponseObject, error)
	// ListBackups The node's own backups (scheduled and manual), newest first
	// (GET /system/backups)
	ListBackups(ctx context.Context, request ListBackupsRequestObject) (ListBackupsResponseObject, error)
	// GetSystemInfo Version, engine, features and the audit chain head
	// (GET /system/info)
	GetSystemInfo(ctx context.Context, request GetSystemInfoRequestObject) (GetSystemInfoResponseObject, error)
	// GetSystemStatus Storage, event pipeline and feed health for the System page
	// (GET /system/status)
	GetSystemStatus(ctx context.Context, request GetSystemStatusRequestObject) (GetSystemStatusResponseObject, error)
	// TestUpstream Check that the proxy can reach an upstream target (connect and HEAD /, no redirects, 3 s)
	// (POST /system/test-upstream)
	TestUpstream(ctx context.Context, request TestUpstreamRequestObject) (TestUpstreamResponseObject, error)
	// GetUpdateStatus Check whether a newer signed release is available
	// (GET /system/update)
	GetUpdateStatus(ctx context.Context, request GetUpdateStatusRequestObject) (GetUpdateStatusResponseObject, error)
	// ApplyUpdate Download, verify and stage or install the latest signed release
	// (POST /system/update/apply)
	ApplyUpdate(ctx context.Context, request ApplyUpdateRequestObject) (ApplyUpdateResponseObject, error)
	// ListTokens Your API tokens (all tokens for an admin)
	// (GET /tokens)
	ListTokens(ctx context.Context, request ListTokensRequestObject) (ListTokensResponseObject, error)
	// CreateToken Create an API token (the secret is shown once)
	// (POST /tokens)
	CreateToken(ctx context.Context, request CreateTokenRequestObject) (CreateTokenResponseObject, error)
	// DeleteToken Revoke a token (your own; an admin may revoke any)
	// (DELETE /tokens/{id})
	DeleteToken(ctx context.Context, request DeleteTokenRequestObject) (DeleteTokenResponseObject, error)
	// ListUsers Users
	// (GET /users)
	ListUsers(ctx context.Context, request ListUsersRequestObject) (ListUsersResponseObject, error)
	// CreateUser Create a user
	// (POST /users)
	CreateUser(ctx context.Context, request CreateUserRequestObject) (CreateUserResponseObject, error)
	// DeleteUser Delete a user (and their sessions and tokens)
	// (DELETE /users/{id})
	DeleteUser(ctx context.Context, request DeleteUserRequestObject) (DeleteUserResponseObject, error)
	// PatchUser Change a user's role, state or password
	// (PATCH /users/{id})
	PatchUser(ctx context.Context, request PatchUserRequestObject) (PatchUserResponseObject, error)
	// ResetUserMFA Clear a user's MFA enrolment (they re-enrol at next sign-in)
	// (POST /users/{id}/reset-mfa)
	ResetUserMFA(ctx context.Context, request ResetUserMFARequestObject) (ResetUserMFAResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

